from pathlib import Path
import subprocess
root=Path(__file__).resolve().parents[1]
overlay=root/'overlay/src/modules/optional/SentinelPresence'
source=(overlay/'SentinelPresence.cpp').read_text()
methods=source[source.index('void loadFactoryDefaults()'):source.index('uint32_t hashSource(')]
out=root/'.build/settings-test';out.mkdir(parents=True,exist_ok=True)
cpp=out/'settings.cpp';cpp.write_text('\n#include <cassert>\n#include <cstring>\n#include <cstdio>\n#include <map>\n#include <string>\n#include <vector>\n#include "SentinelCore.h"\n#include "SentinelPresenceConfig.h"\nstd::map<std::string,std::vector<uint8_t>> storage;\nbool failWrite=false;\nstruct Preferences {\n bool begin(const char*,bool){return true;}void end(){}\n size_t getBytesLength(const char*k){return storage[k].size();}\n size_t getBytes(const char*k,void*p,size_t n){auto &v=storage[k];if(n<v.size())return 0;memcpy(p,v.data(),v.size());return v.size();}\n size_t putBytes(const char*k,const void*p,size_t n){if(failWrite)return 0;auto*b=static_cast<const uint8_t*>(p);storage[k]={b,b+n};return n;}\n bool getBool(const char*k,bool d){return storage[k].empty()?d:storage[k][0];}\n uint16_t getUShort(const char*k,uint16_t d){return storage[k].size()!=2?d:storage[k][0]|uint16_t(storage[k][1])<<8;}\n size_t putBool(const char*k,bool v){return putBytes(k,&v,1);}\n size_t putUShort(const char*k,uint16_t v){return putBytes(k,&v,2);}\n};\nvoid strlcpy(char*d,const char*s,size_t n){strncpy(d,s,n-1);d[n-1]=0;}\nstruct {template<class... A>void printf(const char*,A...){}}Serial;\nSentinelSettings settings{};bool observationEnabled=false;uint16_t observationInterval=15;\n'+methods+'\nint main(){\n loadSettings();assert(validSettings(settings));assert(!strcmp(settings.label,"SENTINEL-1"));\n strcpy(settings.label,"GATE-7");settings.meshChannelIndex=3;observationEnabled=true;observationInterval=60;\n assert(saveSettings());auto saved=storage;settings={};observationEnabled=false;observationInterval=0;\n loadSettings();assert(!strcmp(settings.label,"GATE-7") && settings.meshChannelIndex==3 && observationEnabled && observationInterval==60);\n failWrite=true;assert(!saveSettings());assert(storage==saved);failWrite=false;\n for(const char*k:{"config3","config4","config5","config6"}){\n  storage.clear();std::vector<uint8_t> legacy(sizeof(settings)+32,0xff);memcpy(legacy.data(),&settings,sizeof(settings));storage[k]=legacy;\n  loadSettings();assert(!strcmp(settings.label,"GATE-7"));assert(storage[k]==legacy);assert(saveSettings());assert(storage[k]==legacy);\n }\n storage["ground1"]={1,2,3};loadSettings();assert(!strcmp(settings.label,"SENTINEL-1"));\n storage.clear();storage["config6"]=std::vector<uint8_t>(128,0xff);loadSettings();assert(!strcmp(settings.label,"SENTINEL-1"));\n puts("PASS cold restart persistence, sensor-prefix migration, preserved legacy records, invalid records and write failure");\n}\n')
exe=out/'settings.exe'
subprocess.run(['g++','-std=c++17','-Wall','-Wextra','-Werror','-I'+str(overlay),str(cpp),'-o',str(exe)],check=True)
subprocess.run([str(exe)],check=True)
